  CREATE TABLE #ExpectedQuery4 (
    [NextOrderID] int NULL
  );
  CREATE TABLE #ActualQuery4 (
    [NextOrderID] int NULL
  );
  INSERT INTO #ExpectedQuery4 ([NextOrderID]) VALUES
    (73598);
